WITH unpacked AS (SELECT id, log_ts, latency_ms, payload_json, context['version'] AS version, COALESCE(context['trace'], 'unknown') AS trace_or_default, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, context['trace'] AS trace, SHIFTRIGHT(status_code, 2) AS status_code_high FROM app_logs WHERE latency_ms BETWEEN 1197 AND 1658) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, DATE_TRUNC('HOUR', log_ts) AS hour_window, BIT_OR(latency_ms) AS latency_ms_bit_or, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, MIN(log_ts) AS started_at FROM unpacked GROUP BY CUBE (DATE_TRUNC('DAY', log_ts), DATE_TRUNC('HOUR', log_ts)) HAVING (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 < 1000000;
